class Solution { private var limit=0;fun sufficientSubset(root:TreeNode?,limit:Int):TreeNode?{this.limit=limit;return prune(root,0)};private fun prune(node:TreeNode?,sum:Int):TreeNode?{node?:return null;val current=sum+node.`val`;if(node.left==null&&node.right==null)return if(current>=limit)node else null;node.left=prune(node.left,current);node.right=prune(node.right,current);return if(node.left==null&&node.right==null)null else node} }
